import type { FastifyPluginAsync } from 'fastify';
import { prisma } from '@tallyhook/shared';
import { redis } from '../queue';

type Check = 'postgres' | 'redis';

const checks: Record<Check, () => Promise<unknown>> = {
  postgres: () => prisma.$queryRaw`SELECT 1`,
  redis: () => redis.ping(),
};

export const healthRoutes: FastifyPluginAsync = async (app) => {
  app.get('/healthz', async () => ({ ok: true }));

  app.get('/readyz', async (_req, reply) => {
    const results = await Promise.allSettled(Object.values(checks).map((fn) => fn()));
    const names = Object.keys(checks) as Check[];
    const failed = names.filter((_, i) => results[i].status === 'rejected');
    if (failed.length > 0) {
      return reply.code(503).send({ error: 'not_ready', failed });
    }
    return { ok: true, checks: Object.fromEntries(names.map((n) => [n, 'ok'])) };
  });
};

