import { describe, it, expect, vi, beforeEach } from 'vitest';
import { buildServer } from '../server';

const prismaMock = vi.hoisted(() => ({ $queryRaw: vi.fn() }));
const redisMock = vi.hoisted(() => ({ ping: vi.fn() }));

vi.mock('@tallyhook/shared', async () => {
  const schemas = await vi.importActual<typeof import('@tallyhook/shared/src/schemas')>(
    '@tallyhook/shared/src/schemas',
  );
  return { ...schemas, prisma: prismaMock, logger: false };
});

vi.mock('../queue', () => ({ deliveryQueue: { add: vi.fn() }, redis: redisMock }));

describe('/readyz', () => {
  beforeEach(() => vi.clearAllMocks());

  it('is 200 when both dependencies answer', async () => {
    prismaMock.$queryRaw.mockResolvedValue([{ '?column?': 1 }]);
    redisMock.ping.mockResolvedValue('PONG');
    const res = await buildServer().inject({ method: 'GET', url: '/readyz' });
    expect(res.statusCode).toBe(200);
  });

  it('is 503 and names the failing dependency', async () => {
    prismaMock.$queryRaw.mockResolvedValue([{ '?column?': 1 }]);
    redisMock.ping.mockRejectedValue(new Error('ECONNREFUSED'));
    const res = await buildServer().inject({ method: 'GET', url: '/readyz' });
    expect(res.statusCode).toBe(503);
    expect(res.json()).toEqual({ error: 'not_ready', failed: ['redis'] });
  });
});

